CREATE TABLE git_delivery_metadata ( key TEXT PRIMARY KEY, value TEXT NOT NULL ) STRICT;
CREATE TABLE git_worktrees ( worktree_id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL UNIQUE, plan_fingerprint TEXT NOT NULL, state TEXT NOT NULL, sequence INTEGER NOT NULL, payload TEXT NOT NULL ) STRICT;
CREATE TABLE git_worktree_events ( worktree_id TEXT NOT NULL, sequence INTEGER NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(worktree_id, sequence), FOREIGN KEY(worktree_id) REFERENCES git_worktrees(worktree_id) ) STRICT;
CREATE TABLE git_checkpoints ( checkpoint_id TEXT PRIMARY KEY, worktree_id TEXT NOT NULL UNIQUE, transaction_id TEXT NOT NULL UNIQUE, digest TEXT NOT NULL, payload TEXT NOT NULL ) STRICT;
CREATE TABLE git_commits ( commit_id TEXT PRIMARY KEY, checkpoint_id TEXT NOT NULL UNIQUE, branch_ref TEXT NOT NULL UNIQUE, spec_fingerprint TEXT NOT NULL, state TEXT NOT NULL, sequence INTEGER NOT NULL, payload TEXT NOT NULL ) STRICT;
CREATE TABLE git_commit_events ( commit_id TEXT NOT NULL, sequence INTEGER NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(commit_id, sequence), FOREIGN KEY(commit_id) REFERENCES git_commits(commit_id) ) STRICT;
CREATE TABLE git_product_links ( route_id TEXT NOT NULL PRIMARY KEY CHECK(length(route_id)=36), delivery_id TEXT NOT NULL UNIQUE CHECK(length(delivery_id)=36), thread_id TEXT NOT NULL CHECK(length(thread_id)=36), turn_id TEXT NOT NULL CHECK(length(turn_id)=36), call_id TEXT NOT NULL CHECK(length(call_id)=36), action_kind TEXT NOT NULL CHECK(action_kind IN ('checkpoint','commit')), core_sha256 TEXT NOT NULL CHECK(length(core_sha256)=64 AND core_sha256 NOT GLOB '*[^0-9a-f]*'), route_fingerprint TEXT NOT NULL CHECK(length(route_fingerprint)=64 AND route_fingerprint NOT GLOB '*[^0-9a-f]*'), phase TEXT NOT NULL CHECK(phase IN ('prepared','approved','materials_ready','anchor_intent','anchor_ready','native_patch_intent','native_patch_prepared','native_bridge_closed','delivery_worktree_intent','delivery_worktree_ready','checkpoint_intent','checkpoint_closed','commit_intent','commit_closed','result_closed','unknown','diverged','failed')), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 0 AND 9223372036854775807), payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=67108864), UNIQUE(thread_id,turn_id,call_id), UNIQUE(delivery_id,route_id), UNIQUE(delivery_id,route_id,thread_id,turn_id,call_id) ) STRICT;
CREATE TABLE git_product_link_events ( route_id TEXT NOT NULL CHECK(length(route_id)=36), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 0 AND 9223372036854775807), phase TEXT NOT NULL CHECK(phase IN ('prepared','approved','materials_ready','anchor_intent','anchor_ready','native_patch_intent','native_patch_prepared','native_bridge_closed','delivery_worktree_intent','delivery_worktree_ready','checkpoint_intent','checkpoint_closed','commit_intent','commit_closed','result_closed','unknown','diverged','failed')), payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=67108864), PRIMARY KEY(route_id,sequence), FOREIGN KEY(route_id) REFERENCES git_product_links(route_id) ) STRICT;
CREATE TABLE git_native_bridge_index ( bridge_id TEXT NOT NULL PRIMARY KEY CHECK(length(bridge_id)=36), transaction_id TEXT NOT NULL UNIQUE CHECK(length(transaction_id)=36), route_id TEXT NOT NULL CHECK(length(route_id)=36), anchor_id TEXT NOT NULL CHECK(length(anchor_id)=36), worktree_id TEXT NOT NULL CHECK(length(worktree_id)=36), bridge_sha256 TEXT NOT NULL CHECK(length(bridge_sha256)=64 AND bridge_sha256 NOT GLOB '*[^0-9a-f]*'), FOREIGN KEY(route_id) REFERENCES git_product_links(route_id) ) STRICT;
CREATE TABLE git_object_inventories ( inventory_id TEXT NOT NULL PRIMARY KEY CHECK(length(inventory_id)=36), delivery_id TEXT NOT NULL CHECK(length(delivery_id)=36), route_id TEXT NOT NULL CHECK(length(route_id)=36), phase TEXT NOT NULL CHECK(phase IN ('materials_ready','effect_closed')), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 0 AND 9223372036854775807), inventory_sha256 TEXT NOT NULL CHECK(length(inventory_sha256)=64 AND inventory_sha256 NOT GLOB '*[^0-9a-f]*'), scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64 AND scope_sha256 NOT GLOB '*[^0-9a-f]*'), payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=67108864), FOREIGN KEY(delivery_id,route_id) REFERENCES git_product_links(delivery_id,route_id) ) STRICT;
CREATE TABLE git_object_inventory_events ( inventory_id TEXT NOT NULL CHECK(length(inventory_id)=36), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 0 AND 9223372036854775807), phase TEXT NOT NULL CHECK(phase IN ('materials_ready','effect_closed')), payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=67108864), PRIMARY KEY(inventory_id,sequence), FOREIGN KEY(inventory_id) REFERENCES git_object_inventories(inventory_id) ) STRICT;
CREATE TABLE git_record_publications ( record_kind TEXT NOT NULL CHECK(record_kind IN ('object_inventory','product_link','worktree_event','checkpoint','commit_event')), record_id TEXT NOT NULL CHECK(length(record_id)=36), publication_epoch TEXT NOT NULL CHECK(length(publication_epoch)=36), sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 9223372036854775807), delivery_id TEXT NOT NULL CHECK(length(delivery_id)=36), thread_id TEXT NOT NULL CHECK(length(thread_id)=36), turn_id TEXT NOT NULL CHECK(length(turn_id)=36), call_id TEXT NOT NULL CHECK(length(call_id)=36), route_id TEXT NOT NULL CHECK(length(route_id)=36), previous_prefix TEXT NOT NULL CHECK(length(previous_prefix)=64 AND previous_prefix NOT GLOB '*[^0-9a-f]*'), body_sha256 TEXT NOT NULL CHECK(length(body_sha256)=64 AND body_sha256 NOT GLOB '*[^0-9a-f]*'), body_bytes INTEGER NOT NULL CHECK(body_bytes BETWEEN 1 AND 67108864), prefix_sha256 TEXT NOT NULL CHECK(length(prefix_sha256)=64 AND prefix_sha256 NOT GLOB '*[^0-9a-f]*'), seal BLOB NOT NULL CHECK(length(seal) BETWEEN 1 AND 4096), PRIMARY KEY(record_kind,record_id,publication_epoch,sequence), FOREIGN KEY(delivery_id,route_id,thread_id,turn_id,call_id) REFERENCES git_product_links(delivery_id,route_id,thread_id,turn_id,call_id), CHECK(record_kind!='product_link' OR record_id=route_id) ) STRICT;
CREATE TABLE git_prefix_anchor ( singleton INT NOT NULL PRIMARY KEY CHECK(singleton=1), revision INTEGER NOT NULL CHECK(revision BETWEEN 0 AND 9223372036854775807), genesis_epoch TEXT NOT NULL CHECK(length(genesis_epoch)=36), body_bytes INTEGER NOT NULL CHECK(body_bytes BETWEEN 1 AND 67108864), body_sha256 TEXT NOT NULL CHECK(length(body_sha256)=64 AND body_sha256 NOT GLOB '*[^0-9a-f]*'), payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=67108864), seal BLOB NOT NULL CHECK(length(seal) BETWEEN 1 AND 4096), CHECK(body_bytes=length(CAST(payload AS BLOB))) ) STRICT;
